export type GitOperation = "merge" | "rebase" | "cherryPick" | "revert";

export type GitProblem = { kind: "notInstalled" } | 
/**  macOS's `/usr/bin/git` needs the command line tools */
{ kind: "commandLineToolsMissing" } | 
/**  The `git` found is older than AE's commands need */
{ kind: "tooOld"; version: string } | { kind: "notARepository" } | 
/**  The project is in a folder the repository at `root` ignores */
{ kind: "ignored"; root: string } | 
/**  git failed, with its message */
{ kind: "failed"; message: string };

export type GitProgram = {
	path: string,
	/**  Like `2.56.1` or `2.50.1 (Apple Git-155)` */
	version: string,
};

export type GitRepository = {
	root: string,
	/**
	 *  The project's folder within the repository, like `docs`. `None` when
	 *  the project is the repository's root.
	 */
	projectFolder: string | null,
	/**  The parent repository, when this one is a submodule */
	superproject: string | null,
	/**
	 *  The name commits are made with, and where it's set: the
	 *  `GIT_AUTHOR_NAME` environment variable, `author.name` or `user.name`,
	 *  as git looks
	 */
	userName: GitConfigValue | null,
	/**
	 *  Likewise the email: `GIT_AUTHOR_EMAIL`, `author.email`, `user.email`
	 *  or `EMAIL`
	 */
	userEmail: GitConfigValue | null,
	/**
	 *  When neither is set, the identity git would guess from the computer's
	 *  account and commit with anyway. `None` if git won't guess, and refuses
	 *  to commit
	 */
	guessedIdentity: string | null,
	/**  The signature format (`openpgp`, `ssh`, `x509`) when commits are signed */
	signing: string | null,
	/**  The hooks a commit or push from AE runs, in the order they run */
	hooks: string[],
} & GitHead;

export type GitSetup = {
	/**  `None` when there's no `git` to run */
	git: GitProgram | null,
	/**  Why git can't be used for this project, if it can't */
	problem: GitProblem | null,
	/**  Set when the project is in a repository git can read */
	repository: GitRepository | null,
};

export type GitState = {
	/**  Why git can't be used for the project, if it can't */
	problem: GitProblem | null,
	/**  Set when the project is in a repository git can read */
	tree: GitWorkingTree | null,
};

export type GitWorkingTree = {
	root: string,
	/**  The project folder within the root, like `docs/`. Empty at the root. */
	prefix: string,
	/**  The parent repository's root, when this one is a submodule */
	superproject: string | null,
	/**
	 *  Commits on the branch that aren't on its upstream (to push), newest
	 *  first, up to `COMMIT_LIST_LIMIT`
	 */
	outgoing: GitCommit[],
	/**
	 *  Commits on the upstream that aren't on the branch (to pull), as of the
	 *  last fetch
	 */
	incoming: GitCommit[],
	/**
	 *  Changed, new and conflicted files in the project folder, without
	 *  submodules. Paths are relative to `root`.
	 */
	changes: GitChange[],
	/**
	 *  Everything staged in the repository, in and out of the project folder:
	 *  what a commit would take
	 */
	staged: GitChange[],
	/**  The open entry, when one was asked about */
	entry: GitEntry | null,
} & GitHead;

export type GlobalSettings = {
	general: GeneralSettings,
	appearance: AppearanceSettings,
	copyedit: CopyeditSettings,
	version: number,
};

/**  The user's heading colours. Unset, headings take the editor text colour */
export type HeadingColor = {
	light?: string | null,
	dark?: string | null,
};

export type Highlights = {
	nouns: boolean,
	verbs: boolean,
	adjectives: boolean,
	adverbs: boolean,
	conjunctions: boolean,
};

/**  An image picked for an image prop, which the file has to import */
export type ImageImport = {
	/**  The prop it was picked for */
	prop: string,
	/**  The picked file's name, which the import's binding is named after */
	file_name: string,
	/**  The path to import it from, as the editor writes image paths */
	specifier: string,
};

export type ImportPlan = {
	/**  The import block with everything added */
	imports: string,
	/**  The statements added or changed, in the order they're in the block */
	added: string[],
	/**
	 *  The statement that already has the component's name, if one does. It may
	 *  be something else of the same name, and then the writer's import wins.
	 */
	existing: string | null,
	/**
	 *  The name each picked image or entry is imported or loaded as, by the
	 *  prop it was picked for
	 */
	names: { [key in string]: string },
};

/**  A registered project, as the project list shows it */
export type ListedProject = {
	project: ProjectMetadata,
	/**  Its folder isn't there, usually because it was moved or renamed */
	missing: boolean,
	/**  It's on a drive that isn't connected, so it may well come back */
	disconnected: boolean,
	/**  The site's icon, `public/favicon.{svg,png,ico}`, as an absolute path */
	favicon: string | null,
};

/**  A content file, split for the editor */
export type MarkdownContent = {
	frontmatter: { [key in string]: Value },
	content: string,
	/**
	 *  The frontmatter block as written, from the top of the file through
	 *  the closing `---` (without its line ending), including any byte order
	 *  mark, blank lines and spaces after the fences. Empty when the file has
	 *  none. Saving writes it back unchanged when the frontmatter wasn't edited
	 */
	raw_frontmatter: string,
	imports: string,
	/**
	 *  Why the frontmatter couldn't be read, if it couldn't: the parser's
	 *  error, with line numbers counted from the top of the file. The
	 *  frontmatter is then empty, and saving writes `raw_frontmatter` back
	 *  unchanged
	 */
	frontmatter_error: string | null,
};

export type MdxComponent = {
	name: string,
	/**  Relative path from project root; empty for components from a package */
	file_path: string,
	props: PropInfo[],
	has_slot: boolean,
	description: string | null,
	framework: ComponentFramework,
	/**
	 *  The module a package's components are imported from, e.g. `@astrojs/starlight/components`;
	 *  `None` for the project's own components
	 */
	import_source: string | null,
	/**  Imported by name (`import { Aside } from …`) rather than as its module's default export */
	named_export: boolean,
	/**
	 *  Content inserted inside the tag instead of an empty slot, as a CodeMirror snippet,
	 *  e.g. the `TabItem`s inside `Tabs`
	 */
	slot_template: string | null,
};

/**  A project as opened: its registry entry and its stored settings */
export type OpenedProject = {
	project: ProjectMetadata,
	settings: ProjectSettingsData,
	/**
	 *  It had no current settings file: it's new, or its settings are from
	 *  before version 3 and were moved aside
	 */
	newSettings: boolean,
};

export type ProjectMetadata = {
	/**  Names the project's settings file. Never changes, even if the project moves. */
	id: string,
	name: string,
	/**  Canonical path to the project folder */
	path: string,
	/**  ISO timestamps */
	lastOpened: string,
	created: string,
	/**
	 *  The entry open when the project was last left, relative to the project
	 *  with `/`, so it survives the project moving. None when no file was open.
	 */
	lastEntry: string | null,
};

/**  Every project AE has opened */
export type ProjectRegistry = {
	projects: { [key in string]: ProjectMetadata },
	lastOpenedProject: string | null,
	version: number,
};

/**  Everything AE knows about a project's content */
export type ProjectScan = {
	/**  The content config, relative to the project root, if there is one */
	configPath: string | null,
	/**  Why the config couldn't be read */
	configError: string | null,
	/**  There's no readable config, so the collections are the content folder's subfolders */
	fallback: boolean,
	/**  The site's icon, `public/favicon.{svg,png,ico}`, as an absolute path */
	favicon: string | null,
	projectSettings: ResolvedProjectSettings,
	collections: Collection[],
};

/**  Settings for the whole project. Paths are relative to the project root. */
export type ProjectSettings = {
	/**
	 *  Where collections are looked for when their loader doesn't say, and the
	 *  folder whose subfolders become collections when there's no readable config
	 */
	contentDirectory?: string | null,
	/**  Images go in `<assets>/<collection>/`. Collections can override it. */
	assetsDirectory?: string | null,
	/**
	 *  Write image paths from the project root rather than relative to the file.
	 *  Collections can override it.
	 */
	useAbsoluteAssetPaths?: boolean | null,
	/**  The folders the component builder offers components from */
	mdxComponentsDirectories?: string[] | null,
	/**  Experimental: the component builder adds the import a component needs */
	addComponentImports?: boolean | null,
	/**
	 *  Editing a file's frontmatter puts its keys in schema order, then the
	 *  rest alphabetically
	 */
	reorderFrontmatter?: boolean | null,
	/**
	 *  Experimental: the Git tab in the right sidebar, and its report in
	 *  Project Settings. Off, AE runs no git commands for the project.
	 */
	gitPanel?: boolean | null,
};

/**  A project's stored settings, as the frontend reads and edits them */
export type ProjectSettingsData = {
	project: ProjectSettings,
	/**  Keyed by the collection's name in the content config */
	collections: { [key in string]: CollectionSettings },
};

/**  What was picked for the props whose values the file has to import or load */
export type PropImports = {
	images: ImageImport[],
	entries: EntryImport[],
};

export type PropInfo = {
	name: string,
	prop_type: string,
	kind: PropKind,
	is_optional: boolean,
	/**  The default from destructuring, as source: strings unquoted, anything else verbatim */
	default_value: string | null,
	description: string | null,
};

/**
 *  What kind of value a prop takes, resolved from its TypeScript type.
 *  The component builder picks a control for each kind; `Unknown` gets a text field.
 */
export type PropKind = { kind: "string" } | { kind: "number" } | { kind: "boolean" } | 
/**  A union of string literals, e.g. `'sm' | 'md' | 'lg'`, or a string enum */
{ kind: "literals"; values: string[] } | { kind: "array"; items: PropKind } | { kind: "date" } | 
/**  Astro's `ImageMetadata` */
{ kind: "image" } | 
/**  `CollectionEntry<'blog'>` from `astro:content` */
{ kind: "collectionEntry"; collection: string } | { kind: "unknown" };

/**  What relocating a project did */
export type Relocation = "relocated" | 
/**  Another registered project is at the new folder, so nothing changed */
"alreadyRegistered";

export type Resolved<T> = {
	value: T,
	source: SettingSource,
};

export type ResolvedCollectionSettings = {
	skippedFiles: Resolved<SkippedFiles>,
	titleField: Resolved<string | null>,
	descriptionField: Resolved<string | null>,
	/**  Fields to try for a file's published date, in order */
	publishedDateField: Resolved<string[]>,
	draftField: Resolved<string | null>,
	/**  Unset, the file list sorts by published date, newest first */
	defaultSort: Resolved<DefaultSort | null>,
	newFileType: Resolved<FileType>,
	/**
	 *  How files are named, like `{YYYY-MM-DD}-{slug}`. `{slug}` is the title as a
	 *  slug, and other placeholders are numbers, dates and times. Applied by the
	 *  frontend (`lib/files/file-name-pattern.ts`).
	 */
	fileNamePattern: Resolved<string>,
	/**  Unset, links use the file's relative path */
	urlPattern: Resolved<string | null>,
	/**  Relative to the project root. Images go in `<assets>/<collection>/`. */
	assetsDirectory: Resolved<string>,
	useAbsoluteAssetPaths: Resolved<boolean>,
};

export type ResolvedProjectSettings = {
	/**  Relative to the project root */
	contentDirectory: Resolved<string>,
	/**  Relative to the project root */
	mdxComponentsDirectories: Resolved<string[]>,
	addComponentImports: Resolved<boolean>,
	reorderFrontmatter: Resolved<boolean>,
	gitPanel: Resolved<boolean>,
	/**  The project's default for collections. Relative to the project root. */
	assetsDirectory: Resolved<string>,
	/**  The project's default for collections */
	useAbsoluteAssetPaths: Resolved<boolean>,
};

export type SchemaStatus = 
/**  From the generated JSON schema, with the config's helpers */
"complete" | 
/**
 *  The config has a schema but there's no generated JSON for it, usually
 *  because `astro sync` hasn't run. Only the config's `image()` and
 *  `reference()` helpers are known.
 */
"notGenerated" | 
/**  The JSON schema couldn't be read (see `schema_error`) */
"unreadable" | 
/**  The collection has no schema */
"none";

/**  Where a resolved setting's value came from */
export type SettingSource = 
/**  Set on the collection (or, for project settings, the project) */
"set" | 
/**  Set on the project, for a collection setting */
"project" | 
/**  The global preference */
"global" | 
/**  Read from the content config */
"config" | 
/**  Detected in the schema */
"schema" | 
/**  Astro's or AE's convention */
"convention" | 
/**  Nothing to go on */
"missing";

/**  What the file list does with Markdown files the collection's pattern leaves out */
export type SkippedFiles = "hide" | "dim";

export type SortDirection = "asc" | "desc";

/**  Global settings and the project registry */
export type StoredPreferences = {
	globalSettings: GlobalSettings,
	registry: ProjectRegistry,
	/**
	 *  Files that couldn't be read, so were set aside and replaced with
	 *  defaults, for the frontend to say so. Returned rather than sent as a
	 *  toast, since this runs before the toast listener may be ready.
	 */
	problems: string[],
};

export type Theme = "light" | "dark" | "system";

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

